import json,re
A=json.load(open('auto.json'))
def clean(e):
    e=re.sub(r'^(Yes|No|NO|YES)[,\.!:\s]*','',e).strip()
    return (e[:1].upper()+e[1:]) if e else ''
def short(o,n=70):
    o=o.strip().rstrip('.');return o if len(o)<=n else o[:n-1].rstrip()+'…'
def rat(a):
    corr=a['corr'];o=a['opts'];ex=a['ex']
    cs=[f"“{short(o[i])}”"+(f" – {clean(ex[i]).rstrip('.')}." if clean(ex[i]) else '') for i in corr]
    ws=[f"“{short(o[i])}”"+(f" – {clean(ex[i]).rstrip('.')}." if clean(ex[i]) else '') for i in range(len(o)) if i not in corr]
    head=("Correct:\n"+"\n".join("• "+c for c in cs)) if len(corr)>1 else "Correct: "+cs[0]
    tail="\n\nNot correct:\n"+"\n".join("• "+w for w in ws) if ws else ''
    return head+tail+"\n\n(From your class slides.)"
topic_by_idx={0:'PD',1:'IC',2:'IC',3:'PD',4:'IC',5:'IC',6:'LE',7:'CV',8:'PD',9:'BT',10:'PH',11:'PH',12:'PH',13:'PH',14:'PD',15:'LE',16:'LE',17:'LE',18:'MH',19:'MH',20:'MH',21:'MH',22:'MH',23:'MH',24:'MH',25:'MH',26:'MH',27:'MH',28:None,29:'RF',30:'MN',31:'MN',32:'HP',33:'HP',34:'GI',35:'IC'}
DECK={'Safety':'Safety & Infection Control','Pharmacological':'Pharmacology & Parenteral','Management':'Management of Care','Psychosocial Integrity':'Psychosocial Integrity','Reduction':'Reduction of Risk Potential','Physiological':'Physiological Adaptation','OB and':'OB & Newborn','Health Promotion':'Health Promotion','Pediatrics':'Pediatrics','Basic Care':'Basic Care & Comfort','NCLEX Test':'NCLEX Test-Taking','Reproductive':'Reproductive'}
def label(deck):
    for k,v in DECK.items():
        if k in deck:return 'Class slides – '+v
    return 'Class slides'
out=[]
for i,a in enumerate(A):
    t=topic_by_idx.get(i)
    if t is None:continue
    out.append({'src':label(a['deck']),'t':t,'q':a['stem'],'o':a['opts'],'a':(a['corr'] if len(a['corr'])>1 else a['corr'][0]),'r':rat(a)})
D=' (Answer key not on the slide; worked out with NCLEX reasoning, so check it against your class notes.)'
def M(src,t,q,o,a,r,derived=True):
    out.append({'src':'Class slides – '+src,'t':t,'q':q,'o':o,'a':a,'r':r+("\n\n"+D.strip() if derived else "\n\n(From your class slides.)")})
M('Management of Care','LE',"The nurse is caring for a client who asks the nurse to witness an advance directive. Which of the following actions should the nurse implement?",["Decline the client’s request politely.","Agree to sign the document as a witness.","Notify the PHCP of the client's request.","Help the client locate an unrelated third party."],3,"Witnesses to an advance directive should be impartial: not a relative, not an heir or beneficiary, and in many states not an employee of the care facility or the treating provider. The nurse supports the client’s autonomy by helping find an appropriate witness (an unrelated third party) rather than refusing or signing. State rules vary, so follow facility policy.")
M('Management of Care','LE',"The nurse needs to witness the signature on informed consent forms for multiple clients. Which of the following clients are legally able to sign a consent form for surgery? Select all that apply.",["16-year-old married client scheduled for a C-Section.","59-year-old client who speaks Spanish only.","30-year-old client who just received amoxicillin.","88-year-old client who is blind but alert and oriented.","17-year-old client who needs emergency appendectomy."],[0,2,3],"Correct:\n• 16-year-old married client – an emancipated minor (married under 18) can consent.\n• 30-year-old who received amoxicillin – an antibiotic does not impair the ability to give consent.\n• 88-year-old who is blind but alert and oriented – a disability that does not affect comprehension does not remove the right to sign.\n\nNot correct:\n• Spanish-only speaker – needs an interpreter before consent is informed.\n• 17-year-old needing an appendectomy – a minor who is not emancipated needs a parent or guardian (emergencies may proceed under implied consent).\n\n(From your class slides.)",False)
M('Management of Care','LE',"The nurse is discussing living wills with a client. The client asks the nurse if a living will, prepared 3 years ago, remains in effect. Which response should the nurse provide to the client?",["“Yes, a living will never expire.”","“You need to speak to an attorney.”","“I will call someone to answer your question.”","“It is recommended to review them yearly and update with your health care provider.”"],3,"A living will stays valid until the client changes it, but it should be reviewed regularly (about yearly) and updated with the provider as health and wishes change. The nurse gives accurate teaching directly instead of deflecting to an attorney or another person.")
M('Management of Care','LE',"The nurse is teaching nursing staff about computerized documentation. Which of the following information should the nurse include?",["Document pain findings within the hour of assessment.","Promote care continuity by using standardized care plans.","Omit narrative progress notes for clinical condition changes.","Use predefined statements for abnormal findings while charting by exception."],1,"Electronic records support continuity of care through standardized care plans that every discipline can see. Charting by exception uses predefined statements for NORMAL findings, and abnormal findings and condition changes still require narrative notes, so the other options are wrong.")
M('Basic Care & Comfort','GI',"The nurse in the outpatient clinic is talking with a 22-year-old client who is seeking treatment for constipation and given a prescription and discharge instructions for bisacodyl therapy. Which of the following statements by the client would require follow-up? Select all that apply.",["“I should drink 2 to 4 glasses of water per day.”","“I will take the medication on an empty stomach to obtain quick relief from constipation.”","“I will notify my health care provider if I should experience abdominal pain without any relief.”","“I should make sure that I do not take the medication with an antacid even to prevent gastric upset.”","“I should plan on taking the medication for the rest of my life to prevent any future episodes of discomfort.”"],[0,4],"Bisacodyl is a stimulant laxative for short-term use. Follow-up is needed for: drinking only 2–4 glasses of water (the client should take in about 8–10 glasses a day to help the laxative work and prevent dehydration) and planning to use it for life (long-term use causes dependence and electrolyte loss). Taking it on an empty stomach, reporting unrelieved abdominal pain, and avoiding antacids (they dissolve the enteric coating early) are all correct.")
M('Psychosocial Integrity','PD',"The nurse and unlicensed assistive personnel (UAP) are caring for an agitated client who had physical restraints applied 5 minutes ago. Which of the following interventions would be appropriate for the nurse to assign to the UAP?",["Assessing the client’s behavior.","Monitoring the client’s orientation level.","Providing range-of-motion exercises for the client.","Deciding whether or not to remove the client’s restraints."],2,"UAPs may perform routine, stable tasks such as range of motion and basic care. Assessment, monitoring mental status, and the decision to remove restraints require the RN’s judgment and cannot be delegated.")
M('NCLEX Test-Taking','PD',"The nurse is caring for a group of assigned clients on the medical surgical unit. Which of the following clients should the nurse see first?",["Client with a spinal cord injury who is flushed, diaphoretic.","Client with diabetes mellitus (type 2) who has a finger stick glucose level of 242 mg/dL.","Client with hyperparathyroidism with a calcium level of 11.5 mg/dL.","Client with angina complaining of a headache after receiving prescribed nitroglycerin."],0,"A flushed, diaphoretic client with a spinal cord injury suggests autonomic dysreflexia, a life-threatening emergency (severe hypertension, risk of stroke). The glucose of 242, calcium of 11.5, and a nitroglycerin headache are expected or only mildly abnormal and can wait.")
M('NCLEX Test-Taking','PD',"The UAP reports that a client is complaining of chest pain. Which of the following actions should the nurse perform first?",["Ask the UAP to get a complete set of vital signs on the client.","Call the rapid response team.","Administer prescribed nitroglycerin sublingual tab.","Assess the client."],3,"Assessment comes first in the nursing process. The nurse must evaluate the chest pain before acting, then treat or escalate based on the findings.")
M('NCLEX Test-Taking','PH',"The nurse in the outpatient clinic is talking with a 42-year-old client who has hypertension and is receiving a loop diuretic. Which of the following statements by the client would require follow-up? Select all that apply.",["“I should still follow my low-sodium diet.”","“I will stand slowly from a seated position.”","“I will increase my fluid intake each day to 5L.”","“I should weight myself once a month.”","“I will take the medication at the same time of the day, every day.”"],[2,3],"Requires follow-up: drinking 5 L a day (fluid should not be pushed excessively and should be guided by the provider) and weighing once a month (diuretic clients should weigh daily to track fluid loss or gain). Low-sodium diet, standing slowly to prevent orthostatic hypotension, and a consistent daily dosing time are correct.")
M('NCLEX Test-Taking','RS',"The nurse in the emergency department is caring for a 9-year-old client with asthma. Client reports chest tightness with cough especially at night for 2 evenings. Expiratory wheeze throughout the chest. T 98.6 °F, P 110, RR 28, SpO2 89% on room air. Sitting in tripod position. The nurse should first:",["apply humidified supplemental oxygen at 2L/min via nasal cannula","ask parent about allergens in the home","remind the client how to use metered dose inhaler","check the client’s peak flow with a peak expiratory flow meter"],0,"Airway, breathing, circulation: SpO2 of 89%, tachypnea, wheezing, and tripod positioning show hypoxemia and respiratory distress, so oxygen is first. Allergen history, inhaler teaching, and peak flow come after the client is stabilized (peak flow is also hard to do in acute distress).")
M('NCLEX Test-Taking','PH',"The nurse in the outpatient clinic is caring for a 40-year-old client that is taking an ACE inhibitor. Which actions are indicated for this client? Select all that apply.",["Teach the client to report if a dry cough occurs","Teach the client that the medication should be taken without food.","Advise the client to increase potassium intake.","Female clients who become pregnant should immediately notify the provider."],[0,3],"ACE inhibitors commonly cause a dry cough (report it, the drug may need changing) and are teratogenic, so pregnancy must be reported at once. They cause potassium retention, so clients should NOT increase potassium intake, and most can be taken with or without food.")
M('NCLEX Test-Taking','SK',"A client is post-operative day 4 after an appendectomy. Which findings indicate the client is NOT progressing as expected? Select all that apply.",["Can ambulate in the corridor 2 times a day with minimal assistance.","Jackson-Pratt drain has minimal drainage of 15 mL/day.","Refusing to use the incentive spirometer because it causes too much pain.","Using the client-controlled analgesia (PCA) device as ordered.","States no nausea or vomiting.","Abdominal incision dressing is clean, dry, and intact.","Redness and edema noted at the incision site."],[2,6],"Not progressing: refusing the incentive spirometer (risk of atelectasis and pneumonia, so pain control and teaching are needed) and redness and edema at the incision (possible early wound infection). The rest are expected recovery findings.")
M('Reduction of Risk Potential','RF',"A 72-year-old client on furosemide doubled the dose to catch up and now is drowsy, confused, weak, with numbness and tingling in the hands. ABG: pH 7.48, PaCO2 44 mm Hg, HCO3 30 mEq/L. Which acid-base imbalance is the client most likely experiencing?",["Metabolic acidosis.","Respiratory acidosis.","Metabolic alkalosis.","Respiratory alkalosis."],2,"pH 7.48 is alkalotic. The HCO3 of 30 is high (normal 22–28) and PaCO2 of 44 is normal, so the cause is metabolic. Excess loop diuretic loses H+, K+ and fluid, producing metabolic alkalosis.",False)
M('Reduction of Risk Potential','RF',"The client on furosemide has metabolic alkalosis after taking a doubled dose. Which of the following actions should the nurse take first?",["Check the client’s skin turgor.","Assess the client’s electrolyte value pattern.","Ask the client if salt is added to their food at mealtimes.","Have the client describe typical daily bowel and bladder habits."],1,"Overuse of furosemide can cause hypokalemia, hypocalcemia, and hyponatremia, which explain the weakness, confusion, and tingling. Reviewing the electrolyte pattern directly identifies life-threatening imbalances first. Skin turgor and history questions are lower priority.")
M('OB & Newborn','MN',"A 26-year-old primigravida client at 4 weeks gestation arrives at the outpatient clinic for an initial prenatal visit. Which of the following findings would be consistent with the client’s history? Select all that apply.",["Fatigue.","Nausea.","Quickening.","Breast sensitivity.","Braxton Hicks contractions."],[0,1,3],"Early pregnancy (presumptive signs) includes fatigue, nausea, and breast tenderness. Quickening is first felt around 16–20 weeks (earlier in multiparas), and Braxton Hicks contractions appear in the second and third trimesters.")
M('Pediatrics','PE',"The nurse in the pediatric clinic is caring for a 6-year-old client with recurrent group A streptococcal pharyngitis and inflammation of the conjunctivae. The eyelids are edematous. Which of the following actions should the nurse take first?",["Moisten a clean compress with warm water.","Remind the client to avoid rubbing their eyes.","Instill newly prescribed antibiotic drops in both eyes.","Wipe each client eye beginning at the inner canthus."],0,"Crusted drainage must be softened and removed before medication can reach the eye, so the nurse first prepares a warm, moist compress. Then wipe from the inner to the outer canthus with a clean area of cloth for each eye, instill drops, and teach not to rub the eyes.")
M('Health Promotion','HP',"The community health nurse is preparing to host a seminar about preventive care at the local church. Which of the following information should the nurse include for the seminar?",["Family planning and well-baby care.","Adult screening for blood pressure and cholesterol.","Family focused medical home and ambulatory care.","Rehabilitative programs such as sports medicine and orthopedic."],0,"Preventive care is the primary level of health care, which focuses on health promotion and protection such as family planning and well-baby care. Screening is secondary, and rehabilitation is tertiary.")
M('Health Promotion','HP',"The charge nurse in the long-term-care facility is preparing to deliver an in-service about the secondary level of health care for staff nurses. Which of the following information should the nurse include in the seminar?",["Family planning and well-baby care.","Adult screening for blood pressure and cholesterol.","Family focused medical home and ambulatory care.","Rehabilitative programs such as sports medicine and orthopedic."],1,"Secondary prevention is screening and early diagnosis and treatment, such as adult blood pressure and cholesterol screening. Family planning and well-baby care are primary, and rehabilitation is tertiary.")
M('Safety & Infection Control','IC',"A nurse is working with an emergency response team caring for a group of people who may have been exposed to anthrax while doing farm work but are not exhibiting manifestations of illness. Select three prescriptions that the nurse would anticipate receiving from the primary health care provider (PHCP).",["Ciprofloxacin.","Propranolol.","Hydroxychloroquine.","Furosemide.","Doxycycline.","Clindamycin."],[0,4,5],"Antibiotics are used for anthrax exposure. Ciprofloxacin and doxycycline are the first-line choices and clindamycin is also used in anthrax regimens. Propranolol, hydroxychloroquine, and furosemide do not treat anthrax. Confirm the exact regimen against your class notes.")
# dedupe by stem
seen=set();fin=[]
for q in out:
    k=re.sub(r'[^a-z]','',q['q'].lower())[:80]
    if k in seen:continue
    seen.add(k);fin.append(q)
json.dump(fin,open('bank5.json','w'),ensure_ascii=False)
print(len(fin),'questions;',sum(1 for q in fin if isinstance(q['a'],list)),'select-all')
